from pathlib import Path
from typing import List, Optional

def walk_glob(root_dir: str, pattern: str, exclude: Optional[List[str]] = None) -> List[str]:
    root = Path(root_dir)
    exclude = exclude or []
    matches = []

    if not root.is_dir():
        return matches

    for filepath in root.rglob(pattern):
        if filepath.is_symlink():
            continue

        if not filepath.is_file():
            continue

        if any(part.startswith('.') for part in filepath.relative_to(root).parts):
            continue

        should_exclude = False
        for excl_pattern in exclude:
            if filepath.match(excl_pattern):
                should_exclude = True
                break

        if should_exclude:
            continue

        try:
            matches.append(str(filepath.resolve()))
        except (OSError, ValueError):
            continue

    return sorted(set(matches))
